function freePort():Promise<number>{return new Promise((resolve,reject)=>{const server=createServer();server.once('error',reject);server.listen(0,'127.0.0.1',()=>{const address=server.address();if(!address||typeof address==='string')return reject(new Error('No local port'));server.close(()=>resolve(address.port))})})}
function waitReady(child:ChildProcess):Promise<void>{return new Promise((resolve,reject)=>{let text='';const timer=setTimeout(()=>reject(new Error('Test server did not start')),50000);const done=(chunk:Buffer)=>{text+=chunk.toString();if(text.includes('Ready in')){clearTimeout(timer);resolve()}};child.stdout?.on('data',done);child.stderr?.on('data',done);child.once('exit',code=>{clearTimeout(timer);reject(new Error(`Test server exited (${code})`))})})}
class Browser {cookies=new Map<string,string>();constructor(readonly origin:string){}async request(path:string,init:RequestInit={}){const headers=new Headers(init.headers);if(this.cookies.size)headers.set('cookie',[...this.cookies].map(([k,v])=>`${k}=${v}`).join('; '));const res=await fetch(this.origin+path,{...init,headers,redirect:'manual'});for(const cookie of res.headers.getSetCookie()){const first=cookie.split(';')[0];const at=first.indexOf('=');if(at>0)this.cookies.set(first.slice(0,at),first.slice(at+1));}return res}async login(email:string,password:string){const csrf=await (await this.request('/api/auth/csrf')).json() as {csrfToken:string};const body=new URLSearchParams({csrfToken:csrf.csrfToken,identifier:email,password,callbackUrl:this.origin+'/en/portal'});const response=await this.request('/api/auth/callback/credentials',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',origin:this.origin},body});assert([200,302,303].includes(response.status),'Sign-in failed');}}
